// Calculate comprehensive analytics for the past 7 days
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const twoWeeksAgo = new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000);

// Get data from each sheet via node references
const leads = $('Read Leads').all().map(i => i.json);
const content = $('Read Content Drafts').all().map(i => i.json);
const feedback = $('Read Feedback').all().map(i => i.json);
const waitlist = $('Read Waitlist').all().map(i => i.json);

// --- LEADS METRICS ---
const totalLeads = leads.length;
const newLeadsThisWeek = leads.filter(l => {
  const d = new Date(l.signup_date || l.created_date);
  return d >= weekAgo && d <= now;
}).length;
const newLeadsPrevWeek = leads.filter(l => {
  const d = new Date(l.signup_date || l.created_date);
  return d >= twoWeeksAgo && d < weekAgo;
}).length;

// Leads by source
const leadsBySource = {};
leads.filter(l => {
  const d = new Date(l.signup_date || l.created_date);
  return d >= weekAgo && d <= now;
}).forEach(l => {
  const source = l.source || 'unknown';
  leadsBySource[source] = (leadsBySource[source] || 0) + 1;
});

// --- CONTENT METRICS ---
const totalContent = content.length;
const contentThisWeek = content.filter(c => {
  const d = new Date(c.created_date || c.date);
  return d >= weekAgo && d <= now;
}).length;
const approvedContent = content.filter(c => (c.status || '').toLowerCase() === 'approved').length;
const pendingContent = content.filter(c => (c.status || '').toLowerCase() === 'pending').length;
const publishedContent = content.filter(c => (c.status || '').toLowerCase() === 'published').length;

// --- FEEDBACK METRICS ---
const totalFeedback = feedback.length;
const feedbackThisWeek = feedback.filter(f => {
  const d = new Date(f.timestamp || f.date);
  return d >= weekAgo && d <= now;
}).length;
const ratings = feedback.map(f => parseFloat(f.rating)).filter(r => !isNaN(r));
const avgRating = ratings.length > 0 ? (ratings.reduce((a, b) => a + b, 0) / ratings.length).toFixed(1) : 'N/A';
const npsScore = feedback.filter(f => f.would_recommend === true || f.would_recommend === 'true').length;
const npsPercent = totalFeedback > 0 ? ((npsScore / totalFeedback) * 100).toFixed(0) : 'N/A';

// --- WAITLIST METRICS ---
const waitlistSize = waitlist.length;
const newWaitlistThisWeek = waitlist.filter(w => {
  const d = new Date(w.signup_date || w.date);
  return d >= weekAgo && d <= now;
}).length;

// --- SIGNUPS & CONVERSIONS ---
const totalSignups = leads.filter(l => (l.status || '').toLowerCase() === 'active' || (l.status || '').toLowerCase() === 'converted').length;
const conversionRate = totalLeads > 0 ? ((totalSignups / totalLeads) * 100).toFixed(1) : '0.0';

// --- REFERRALS ---
const totalReferrals = leads.filter(l => (l.source || '').toLowerCase() === 'referral').length;
const referralsThisWeek = leads.filter(l => {
  const d = new Date(l.signup_date || l.created_date);
  return (l.source || '').toLowerCase() === 'referral' && d >= weekAgo && d <= now;
}).length;

// --- WEEK OVER WEEK ---
const wowGrowth = newLeadsPrevWeek > 0 
  ? (((newLeadsThisWeek - newLeadsPrevWeek) / newLeadsPrevWeek) * 100).toFixed(1) 
  : (newLeadsThisWeek > 0 ? '100.0' : '0.0');
const wowTrend = parseFloat(wowGrowth) > 0 ? '📈' : (parseFloat(wowGrowth) < 0 ? '📉' : '➡️');

const weekStart = weekAgo.toISOString().split('T')[0];
const weekEnd = now.toISOString().split('T')[0];

return [{
  json: {
    week_start: weekStart,
    week_end: weekEnd,
    total_leads: totalLeads,
    new_leads_this_week: newLeadsThisWeek,
    new_leads_prev_week: newLeadsPrevWeek,
    leads_by_source: leadsBySource,
    total_content_created: totalContent,
    content_this_week: contentThisWeek,
    content_approved: approvedContent,
    content_pending: pendingContent,
    content_published: publishedContent,
    total_signups: totalSignups,
    conversion_rate: conversionRate,
    total_referrals: totalReferrals,
    referrals_this_week: referralsThisWeek,
    total_feedback: totalFeedback,
    feedback_this_week: feedbackThisWeek,
    avg_feedback_rating: avgRating,
    nps_recommend_percent: npsPercent,
    waitlist_size: waitlistSize,
    new_waitlist_this_week: newWaitlistThisWeek,
    week_over_week_growth: wowGrowth,
    wow_trend: wowTrend
  }
}];

